<script setup lang="ts">import{computed,ref}from'vue';import StarField from'./components/StarField.vue';import{nextStoryPage,storyPages}from'./composables/story';const page=ref(-1);const current=computed(()=>page.value<0?null:storyPages[page.value]);const advance=()=>page.value=nextStoryPage(page.value)</script>
<template><main class="story-app" :class="`page-${page}`"><StarField/><div class="moon-photo" aria-hidden="true"/><div class="veil" aria-hidden="true"/><button class="story-tap" aria-label="切换下一页月光故事" @click="advance"><Transition name="page" mode="out-in"><section v-if="!current" key="cover" class="story-card cover"><p class="kicker">MOONLIGHT LETTER</p><h1>月色寄相思</h1><p class="cover-line">山海搁万里</p><p class="cover-line">中秋愿你无忧</p><span class="tap-hint">轻触屏幕 · 开启月光</span></section><section v-else :key="page" class="story-card"><p class="kicker">{{current.kicker}}</p><div class="copy"><h2>{{current.title}}</h2><p v-for="line in current.lines" :key="line">{{line}}</p></div><footer><span>{{current.note}}</span><i>{{page+1}} / {{storyPages.length}}</i></footer></section></Transition></button></main></template>
